### 3. Distributed Tracing Middleware (`Middleware/DistributedTracingMiddleware.cs`)

This middleware extracts existing trace identifiers or generates new ones (`X-Correlation-ID`, `X-Request-ID`), injects them into the HTTP request headers for downstream propagation, and appends them to outgoing response headers.

```csharp
using System.Diagnostics;

namespace CloudNativeApiGateway.Middleware;

public class DistributedTracingMiddleware
{
    private readonly RequestDelegate _next;
    private const string CorrelationIdHeaderName = "X-Correlation-ID";
    private const string RequestIdHeaderName = "X-Request-ID";

    public DistributedTracingMiddleware(RequestDelegate next)
    {
        _next = next;
    }

    public async Task InvokeAsync(HttpContext context)
    {
        // 1. Extract or generate Correlation ID
        if (!context.Request.Headers.TryGetValue(CorrelationIdHeaderName, out var correlationId))
        {
            correlationId = Activity.Current?.Id ?? Guid.NewGuid().ToString();
            context.Request.Headers[CorrelationIdHeaderName] = correlationId;
        }

        // 2. Extract or generate Request ID
        if (!context.Request.Headers.TryGetValue(RequestIdHeaderName, out var requestId))
        {
            requestId = context.TraceIdentifier;
            context.Request.Headers[RequestIdHeaderName] = requestId;
        }

        // 3. Enrich logging scope with tracing context
        using (Microsoft.Extensions.Logging.Abstractions.NullLogger.BeginScope(
            new Dictionary<string, object> 
            {
                ["CorrelationId"] = correlationId.ToString(),
                ["RequestId"] = requestId.ToString()
            }))
        {
            // 4. Attach tracing headers to the outgoing response
            context.Response.OnStarting(() =>
            {
                context.Response.Headers[CorrelationIdHeaderName] = correlationId;
                context.Response.Headers[RequestIdHeaderName] = requestId;
                return Task.CompletedTask;
            });

            await _next(context);
        }
    }
}
```

